        // x := floor(x/2)
        x = x >> 1u8;

        // Connect bit-operations to the recursive definition:
        // For nat x0 = old(x), we have:
        //   (x0 % 2) is the low bit, and (x0 / 2) is x0 >> 1.
        // Thus popcount8(x0) = (x0 % 2) + popcount8(x0/2).
        // The updates to cnt and x preserve:
        //   cnt + popcount8(x) == popcount8(n).
